import { registerPerson, signJwt, buildSixLayerClaims } from '@projexlight/sdk-identity';
const result = await registerPerson({ email, password });
const token = signJwt(buildSixLayerClaims({ person_id: result.person.person_id, email, actor_kind: 'human', mfa_methods: ['pwd'] }));

await fetch('/api/auth/login', { method: 'POST', body: JSON.stringify({ email, password }) });
await fetch('/api/mfa/challenge', { headers: { Authorization: 'Bearer ' + token } });
const r = await fetch('/api/mfa/verify', { method: 'POST', body: JSON.stringify({ challenge_id, otp }) });
const { token: fullToken } = await r.json();

// Customer's IdP fetches SP metadata at GET /saml/<tenant_id>/metadata
// User signs in at IdP; IdP POSTs SAMLResponse to our ACS
await fetch('/saml/' + tenant_id + '/acs', { method: 'POST', body: new URLSearchParams({ SAMLResponse }) });

const reqRes = await fetch('/api/impersonation/request', { method: 'POST', body: JSON.stringify({ target_tenant_id, ticket_ref, justification }) });
const { grant_id } = await reqRes.json();
await fetch('/api/impersonation/' + grant_id + '/approve', { method: 'POST' });
await fetch('/api/impersonation/' + grant_id + '/end', { method: 'POST' });
